$source=@'
using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;
public class CallsDecrypt {
static int U(byte[]b,int p){return b[p]*256+b[p+1];}static uint V(byte[]b,int p){return(uint)((b[p]<<24)|(b[p+1]<<16)|(b[p+2]<<8)|b[p+3]);}
static byte[] Slice(byte[]b,int p,int n){var a=new byte[n];Array.Copy(b,p,a,0,n);return a;}
static byte[] Hk(byte[]secret,string label,int len){var l=Encoding.ASCII.GetBytes("tls13 "+label);var info=new byte[4+l.Length];info[0]=(byte)(len>>8);info[1]=(byte)len;info[2]=(byte)l.Length;Array.Copy(l,0,info,3,l.Length);var result=new List<byte>();byte[] prev=new byte[0];for(byte i=1;result.Count<len;i++){var msg=prev.Concat(info).Concat(new byte[]{i}).ToArray();using(var h=new HMACSHA384(secret))prev=h.ComputeHash(msg);result.AddRange(prev);}return result.Take(len).ToArray();}
public static void Run(string path,string keys,string output){var logs=new Dictionary<string,byte[]>();foreach(var line in File.ReadLines(keys)){var a=line.Split(' ',StringSplitOptions.RemoveEmptyEntries);if(a.Length==3)logs[a[1]+" "+a[0]]=Convert.FromHexString(a[2]);}var b=File.ReadAllBytes(path);var streams=new Dictionary<string,SortedDictionary<uint,byte[]>>();for(int p=24;p+16<b.Length;){int n=BitConverter.ToInt32(b,p+8),s=p+16,end=s+n,ip=s+14;if(end>b.Length)break;if(U(b,s+12)==2048&&b[ip+9]==6){int tr=ip+(b[ip]&15)*4,sp=U(b,tr),dp=U(b,tr+2);if(sp==5061||dp==5061){int d=tr+(b[tr+12]>>4)*4,len=ip+U(b,ip+2)-d;if(len>0){string src=string.Join(".",Slice(b,ip+12,4)),dst=string.Join(".",Slice(b,ip+16,4)),k=src+":"+sp+">"+dst+":"+dp;if(!streams.ContainsKey(k))streams[k]=new SortedDictionary<uint,byte[]>();streams[k][V(b,tr+4)]=Slice(b,d,len);}}}p=end;}
var flat=streams.ToDictionary(k=>k.Key,k=>k.Value.Values.SelectMany(x=>x).ToArray());var randoms=new Dictionary<string,string>();foreach(var kv in flat){var a=kv.Value;if(a.Length>43&&a[0]==22&&a[5]==1){string r=Convert.ToHexString(Slice(a,11,32)).ToLower();randoms[kv.Key]=r;string[] sides=kv.Key.Split('>');randoms[sides[1]+">"+sides[0]]=r;}}
using(var w=new StreamWriter(output)){foreach(var kv in flat){if(!randoms.ContainsKey(kv.Key))continue;string r=randoms[kv.Key],side=kv.Key.StartsWith("10.20.200.5:5061")?"SERVER":"CLIENT";var secrets=new List<byte[]>();foreach(var kind in new[]{"_HANDSHAKE_TRAFFIC_SECRET","_TRAFFIC_SECRET_0"})if(logs.ContainsKey(r+" "+side+kind))secrets.Add(logs[r+" "+side+kind]);var seq=new ulong[secrets.Count];var a=kv.Value;w.WriteLine("FLOW "+kv.Key);for(int p=0;p+5<=a.Length;){int n=U(a,p+3);if(p+5+n>a.Length)break;if(a[p]==23){for(int j=0;j<secrets.Count;j++){var key=Hk(secrets[j],"key",32);var iv=Hk(secrets[j],"iv",12);for(int z=0;z<8;z++)iv[11-z]^=(byte)(seq[j]>>(8*z));var plain=new byte[n-16];try{using(var aes=new AesGcm(key,16))aes.Decrypt(iv,Slice(a,p+5,n-16),Slice(a,p+5+n-16,16),plain,Slice(a,p,5));seq[j]++;int e=plain.Length-1;while(e>=0&&plain[e]==0)e--;if(e>=0&&plain[e]==23)w.WriteLine(Encoding.UTF8.GetString(plain,0,e));break;}catch(CryptographicException){}}}p+=5+n;}}}
}}
'@
Add-Type -TypeDefinition $source
[CallsDecrypt]::Run((Join-Path $PWD 'DontLeaveMeHanging.pcap'),(Join-Path $PWD 'pbx_diag\pbx-diag-20261008\tls-keys.log'),(Join-Path $PWD 'sip_decrypted.txt'))
